import{_ as e,c as i,o as t,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Finder 同期拡張機能","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/finder-sync.md","filePath":"ja/guide/finder-sync.md","lastUpdated":1794112334000}'),o={name:"ja/guide/finder-sync.md"};function n(l,a,d,s,c,h){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="finder-同期拡張機能" tabindex="-1">Finder 同期拡張機能 <a class="header-anchor" href="#finder-同期拡張機能" aria-label="Permalink to &quot;Finder 同期拡張機能&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>Nicasa Finder 同期拡張機能は macOS の Finder にツールバーボタンを追加し、Nicasa のメインアプリを開かずに画像ファイルを素早く処理できるようにします。</p><h3 id="機能" tabindex="-1">機能 <a class="header-anchor" href="#機能" aria-label="Permalink to &quot;機能&quot;">​</a></h3><ul><li><strong>画像オプティマイザ</strong>：選択した画像を圧縮・最適化</li><li><strong>AI 画像エディター</strong>：選択した画像を AI で編集（修復、強化、塗りつぶしなど）</li><li><strong>Finder ツールバーからの素早いアクセス</strong></li><li><strong>複数の画像を同時に選択可能</strong></li></ul><h2 id="インストールと設定" tabindex="-1">インストールと設定 <a class="header-anchor" href="#インストールと設定" aria-label="Permalink to &quot;インストールと設定&quot;">​</a></h2><h3 id="nicasa-アプリからのインストール" tabindex="-1">Nicasa アプリからのインストール <a class="header-anchor" href="#nicasa-アプリからのインストール" aria-label="Permalink to &quot;Nicasa アプリからのインストール&quot;">​</a></h3><p>Finder 同期拡張機能は Nicasa 本体に含まれています。アプリをインストールしたら、拡張機能を有効にします：</p><ol><li><strong>システム設定</strong> &gt; <strong>機能拡張</strong> &gt; <strong>Finder 機能拡張</strong> を開きます</li><li><strong>Nicasa Finder Sync</strong> をオンにします</li></ol><h3 id="ツールバーボタン" tabindex="-1">ツールバーボタン <a class="header-anchor" href="#ツールバーボタン" aria-label="Permalink to &quot;ツールバーボタン&quot;">​</a></h3><p>有効にすると、Finder のツールバーに Nicasa アイコンが表示されます。</p><p>表示されない場合：</p><ol><li>Finder のツールバーを右クリックします</li><li><strong>ツールバーをカスタマイズ…</strong> を選択します</li><li>Nicasa ボタンを所定の位置にドラッグします</li></ol><h2 id="finder-ツールバーボタンの使い方" tabindex="-1">Finder ツールバーボタンの使い方 <a class="header-anchor" href="#finder-ツールバーボタンの使い方" aria-label="Permalink to &quot;Finder ツールバーボタンの使い方&quot;">​</a></h2><h3 id="ファイルの選択" tabindex="-1">ファイルの選択 <a class="header-anchor" href="#ファイルの選択" aria-label="Permalink to &quot;ファイルの選択&quot;">​</a></h3><p>Finder を開き、1 つ以上の画像を選択します。対応形式：</p><ul><li><code>.jpg</code>、<code>.jpeg</code>、<code>.png</code>、<code>.gif</code>、<code>.bmp</code>、<code>.webp</code>、<code>.svg</code>、<code>.tiff</code>、<code>.ico</code></li></ul><h3 id="メニューの使用" tabindex="-1">メニューの使用 <a class="header-anchor" href="#メニューの使用" aria-label="Permalink to &quot;メニューの使用&quot;">​</a></h3><p>Nicasa のツールバーボタンをクリックし、次を選択します：</p><table tabindex="0"><thead><tr><th>オプション</th><th>説明</th></tr></thead><tbody><tr><td><strong>画像オプティマイザ</strong></td><td>選択した画像を圧縮・最適化します</td></tr><tr><td><strong>AI 画像エディター</strong></td><td>選択した画像を Nicasa の AI エディターで開き、修復・強化・インペイントを行います</td></tr></tbody></table><blockquote><p>⚠️ <strong>注意</strong>：ファイルが選択されていない場合、ボタンはビープ音を鳴らし、操作は実行されません。</p></blockquote><h3 id="ワークフロー" tabindex="-1">ワークフロー <a class="header-anchor" href="#ワークフロー" aria-label="Permalink to &quot;ワークフロー&quot;">​</a></h3><ol><li>Finder で画像を選択します</li><li>Nicasa のツールバーボタンをクリック → 目的の操作を選択します</li><li>Nicasa アプリが自動的に起動し、選択した画像を処理します</li></ol><h2 id="ヒント" tabindex="-1">ヒント <a class="header-anchor" href="#ヒント" aria-label="Permalink to &quot;ヒント&quot;">​</a></h2><ul><li>最良の結果を得るには、アクセス権のあるフォルダ内の画像を選択してください</li><li>複数のファイルを一度に選択できます</li><li>画像が開かない場合は、対応形式であるか確認してください</li><li>この拡張機能は macOS のサンドボックスと問題なく連携します。アクセスの許可は初回のみ必要です</li></ul>',25)])])}const b=e(o,[["render",n]]);export{g as __pageData,b as default};
